export const OVERLAYS = {"poa-clinical--poa-edema":{"poa-clinical--poa-edema--fluid-analysis-ตอนที่-2-transudate-modified-transudate-exudate":{"claims":[{"id":"poa-clinical--poa-edema--fluid-analysis-ตอนที่-2-transudate-modified-transudate-exudate--v1","statement":"Total protein (TP) ร่วมกับ total nucleated cell count (TNCC) คือคู่ค่าที่ใช้จัดประเภท effusion ออกเป็น transudate, modified transudate และ exudate โดย transudate มักมีสาเหตุจาก hypoalbuminemia ส่วน inflammatory exudate มี TP สูงและมีเซลล์อักเสบเป็นหลัก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-2672538","locator":"19(4):743-68","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The TP, TNCC, and general cytologic examination can be performed easily, quickly, and inexpensively in-house. The TP and TNCC are used to classify effusions as transudates, modified transudates, or exudates. Transudates usually are caused b"}},{"id":"poa-clinical--poa-edema--fluid-analysis-ตอนที่-2-transudate-modified-transudate-exudate--v2","statement":"ในสุนัข ผลต่างของ glucose ระหว่างเลือดกับน้ำในช่องท้อง (blood-to-fluid glucose difference) มากกว่า 20 mg/dL มีความไว 100% และความจำเพาะ 100% ในการแยก septic peritoneal effusion ออกจาก non-septic ส่วนในแมวมีความไว 86% และความจำเพาะ 100%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12692761","locator":"32(2):161-6","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A blood-to-fluid glucose (BFG) difference > 20 mg/dL was 100% sensitive and 100% specific for the diagnosis of septic peritoneal effusion in dogs. In 7 dogs in which it was evaluated, a blood-to-fluid lactate (BFL) difference < -2.0 mmol/L "}}]},"poa-clinical--poa-edema--fluid-analysis-ตอนที่-1-ดูสีของน้ำ":{"claims":[{"id":"poa-clinical--poa-edema--fluid-analysis-ตอนที่-1-ดูสีของน้ำ--v1","statement":"Chylous effusion มี triglyceride ในน้ำสูงกว่า nonchylous effusion อย่างมีนัยสำคัญ และมี cholesterol/triglyceride ratio ต่ำกว่าอย่างมีนัยสำคัญ ขณะที่ระดับ cholesterol ในน้ำและค่าใน serum ไม่ต่างกันระหว่างสองกลุ่ม","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-3944008","locator":"188(1):49-51","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The pleural fluid triglyceride concentrations were significantly higher (P less than 0.05) and the pleural cholesterol/triglyceride ratios were significantly lower (P less than 0.05) in chylous effusions than in nonchylous effusions in all "}},{"id":"poa-clinical--poa-edema--fluid-analysis-ตอนที่-1-ดูสีของน้ำ--v2","statement":"ในสุนัข การใช้ creatinine ในน้ำช่องท้อง ≥ 2.1 mg/dL ร่วมกับ fluid:serum creatinine ratio ≥ 1.25 ให้ความแม่นยำ 99.0% ในการวินิจฉัย uroperitoneum ทางห้องปฏิบัติการ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35181924","locator":"51(1):107-111","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The results showed that 83.3% of UG and 12.7% of NUG abdominal fluid cases were not classified as transudates or exudates. The use of specific cutoffs for fluid creatinine concentrations (≥2.1 mg/dL) and fluid:serum creatinine ratios (Cf: C"}}]},"poa-clinical--poa-edema--pleural-effusion-และ-pericardial-effusion":{"claims":[{"id":"poa-clinical--poa-edema--pleural-effusion-และ-pericardial-effusion--v1","statement":"Nephrotic syndrome ในสุนัขนิยามด้วยการพบ hypoalbuminemia, hypercholesterolemia, proteinuria และ extravascular fluid accumulation ร่วมกัน ซึ่งยืนยันว่า protein losing nephropathy เป็นเส้นทางที่ทำให้เกิด hypoalbuminemia แล้วนำไปสู่การสะสมของเหลวนอกหลอดเลือด","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21281353","locator":"25(2):206-14","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-01","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"NS was defined as the concurrent presence of hypoalbuminemia, hypercholesterolemia, proteinuria, and extravascular fluid accumulation. ... Median survival was significantly shorter for NS (12.5 days) versus NNGD dogs (104.5 days)."}}]},"poa-clinical--poa-edema--edema-คืออะไร-และแรงตาม-starling":{"claims":[{"id":"poa-clinical--poa-edema--edema-คืออะไร-และแรงตาม-starling--v1","statement":"สมดุลของของเหลวในเนื้อเยื่อ การควบคุมปริมาตร plasma และการเกิด edema ทางคลินิก ถูกกำกับด้วย Starling principle ของ microvascular fluid exchange โดยแรงหลักคือผลต่างของ hydrostatic pressure และผลต่างของ colloid osmotic (oncotic) pressure คร่อมผนัง microvessel ร่วมกับ hydraulic conductance และพื้นที่ผิวของผนังหลอดเลือดที่กำหนดอัตราการกรอง","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33889604","locator":"Starling Forces section","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Tissue fluid balance, plasma volume regulation and clinical oedema formation are governed by the Starling principle of microvascular fluid exchange."}},{"id":"poa-clinical--poa-edema--edema-คืออะไร-และแรงตาม-starling--v2","statement":"ของเหลวที่ถูกกรองออกไปคั่งอยู่ใน interstitium กลับเข้าสู่ระบบไหลเวียนโดยเส้นทางหลักคือ lymphatics โดย efferent lymph ถูกส่งต่อไปยัง thoracic duct แล้วคืนสู่กระแสเลือดที่หลอดเลือดดำใหญ่ ทำให้สมดุลของเหลวในเนื้อเยื่อส่วนใหญ่ขึ้นกับการทำงานของ lymphatics อย่างวิกฤต","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33889604","locator":"The Extravascular Circulation of Extracellular Fluid section","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The remainder is propelled as efferent lymph to the thoracic duct, and thereby returned to the blood stream in the great veins."}},{"id":"poa-clinical--poa-edema--edema-คืออะไร-และแรงตาม-starling--v3","statement":"แผนภาพ capillary ที่ HP ลดจากปลาย arterial ไปปลาย venous โดย OP คงที่ และสรุปว่า HP เป็นตัวเปลี่ยนทิศทางการไหลของของเหลว (คือมีการดูดกลับที่ปลาย venous) เป็นคำอธิบายแบบดั้งเดิม หลักฐานปัจจุบันชี้ว่าในเนื้อเยื่อส่วนใหญ่ microvascular absorption เกิดขึ้นเพียงชั่วคราว และในภาวะ steady state มี filtration เล็กน้อยตลอด แม้กระทั่งที่ venule","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-20200043","locator":"Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Sum-of-forces evidence and direct observations show that microvascular absorption is transient in most tissues; slight filtration prevails in the steady state, even in venules."}}]},"poa-clinical--poa-edema--subcutaneous-edema-localized-กับ-generalized":{"claims":[{"id":"poa-clinical--poa-edema--subcutaneous-edema-localized-กับ-generalized--v1","statement":"impaired lymphatic drainage ทำให้เกิดการบวมเฉพาะที่ ตามนิยามของ lymphedema ซึ่งเป็นความผิดปกติของระบบ lymphatic vascular ที่มีลักษณะเด่นคือการไหลกลับของ lymph บกพร่องร่วมกับการบวมของรยางค์ สนับสนุนการวาง impaired lymphatic drainage ไว้ใต้กลุ่ม localized subcutaneous edema","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16952986","locator":"Abstract, opening sentence","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Lymphedema is a disorder of the lymphatic vascular system characterized by impaired lymphatic return and swelling of the extremities."}},{"id":"poa-clinical--poa-edema--subcutaneous-edema-localized-กับ-generalized--v2","statement":"ในสุนัข ความผิดปกติของระบบ lymphatic แสดงออกเป็นการบวมเฉพาะที่ของรยางค์ (limb edema) ได้จริง ดังรายงานในสุนัขพันธุ์ whippet เพศผู้อายุ 2 ปี 2 ตัวที่เป็นพี่น้องกัน ซึ่งได้รับการวินิจฉัยว่ามีทั้ง idiopathic chylothorax และ limb edema","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-22547848","locator":"Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Idiopathic chylothorax and limb edema was diagnosed in two 2-year-old male whippet siblings."}},{"id":"poa-clinical--poa-edema--subcutaneous-edema-localized-กับ-generalized--v3","statement":"แม้สไลด์จะวาง hypoalbuminemia ไว้ใต้ generalized subcutaneous edema เพียงกลุ่มเดียว แต่ระดับ albumin ที่ต่ำไม่ได้ทำให้เกิดบวมเสมอไป เพราะ albumin คิดเป็นราว 65% ของ plasma colloid osmotic pressure ส่วน globulins มีส่วนอีกราว 35% และ hypoalbuminaemia ที่พบบ่อยในผู้ป่วยวิกฤตก็ไม่ได้มาพร้อมกับ colloid osmotic pressure ที่ลดลงเสมอไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-33889604","locator":"Starling Forces section, discussion of plasma colloid osmotic pressure","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Hypoalbuminaemia is a common finding in critical illness, but is not invariably accompanied by reduced plasma colloid osmotic pressure."}}]},"poa-clinical--poa-edema--pulmonary-edema":{"claims":[{"id":"poa-clinical--poa-edema--pulmonary-edema--v1","statement":"pulmonary edema ที่ไม่ได้เกิดจากหัวใจ (noncardiogenic pulmonary edema) ในสุนัขและแมว คือการคั่งของของเหลวผิดปกติใน lung interstitium หรือ alveoli ที่เกิดจากการเปลี่ยนแปลงของ vascular permeability, hydrostatic pressure ในหลอดเลือดปอด หรือทั้งสองอย่างร่วมกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36815753","locator":"Abstract, Data sources/Summary","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"It can be due to changes in vascular permeability, hydrostatic pressure in the pulmonary vasculature, or a combination thereof."}},{"id":"poa-clinical--poa-edema--pulmonary-edema--v2","statement":"สาเหตุของ noncardiogenic pulmonary edema ในสุนัขและแมว รวมถึงภาวะอักเสบทั้งภายในปอดและในเนื้อเยื่อที่อยู่ห่างออกไป (ARDS), การอุดกั้นทางเดินหายใจ, โรคทางระบบประสาทเช่นบาดเจ็บที่ศีรษะหรือชัก, electrocution, การขยายปอดที่แฟบกลับ และการจมน้ำ ซึ่งครอบคลุมสาเหตุ inflammation, electrocution และ trauma ที่สไลด์จัดไว้ใต้ impaired vascular permeability","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36815753","locator":"Abstract, list of possible causes","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Possible causes include inflammatory states within the lung or in remote tissues (acute respiratory distress syndrome [ARDS]), airway obstruction (post-obstructive pulmonary edema), neurologic disease such as head trauma or seizures (neurog"}},{"id":"poa-clinical--poa-edema--pulmonary-edema--v3","statement":"เมื่อสงสัยสาเหตุจากหัวใจ แนวทาง consensus ของ ACVIM แนะนำให้ทำ thoracic radiography ในผู้ป่วยทุกรายเพื่อประเมินความสำคัญทาง hemodynamic ของโรคลิ้นหัวใจ และแนะนำ echocardiography โดยผู้ตรวจที่มีประสบการณ์เพื่อระบุสาเหตุของเสียงฟู่และความรุนแรงของการขยายของห้องหัวใจ ซึ่งรองรับลำดับ radiography แล้วตามด้วย echocardiography ที่สไลด์วางไว้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30974015","locator":"Section 6.2.1 Recommendations for diagnosis and further categorization of Stage B","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Echocardiography, performed by an experienced operator, is recommended to definitively identify the cause of the murmur, answer specific questions regarding the severity of cardiac chamber enlargement, and identify comorbidities."}}]},"poa-clinical--poa-edema--effusion-และ-7-fs-ของ-abdominal-enlargement":{"claims":[{"id":"poa-clinical--poa-edema--effusion-และ-7-fs-ของ-abdominal-enlargement--v1","statement":"การจำแนก effusion ตามช่องลำตัวเป็น abdominal, thoracic (pleural) และ pericardial effusion เป็นกรอบมาตรฐาน และการประเมินทางห้องปฏิบัติการของน้ำจากทั้งสามช่องเป็นเครื่องมือวินิจฉัยที่มีประโยชน์ในการประเมินโรคที่ทำให้เกิดการคั่งของของเหลว","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-12512378","locator":"Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The laboratory evaluation of abdominal, thoracic, and pericardial effusions is a useful diagnostic tool for the assessment of disease states that result in fluid accumulation."}}]},"poa-clinical--poa-edema--abdominal-effusion-4-สาขาสาเหตุ-และ-cut-off-ของ-albumin":{"claims":[{"id":"poa-clinical--poa-edema--abdominal-effusion-4-สาขาสาเหตุ-และ-cut-off-ของ-albumin--v1","statement":"ในสุนัขที่มี transudative abdominal effusion portal hypertension คือแรงหลักที่ทำให้เกิดน้ำในช่องท้อง ทั้งในกลุ่มที่มีโรคตับและทางเดินน้ำดี และในกลุ่มที่มีสาเหตุอื่น สนับสนุนการวาง increased hydrostatic pressure ซึ่งก็คือ portal hypertension ไว้เป็นสาขาแรกของสาเหตุ abdominal effusion","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11110383","locator":"Abstract, conclusions; J Vet Intern Med 2000;14(6):613-8","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"These findings suggest that portal hypertension is a predominant force in formation of transudative abdominal effusion in dogs with hepatobiliary disease and in dogs with other disorders."}},{"id":"poa-clinical--poa-edema--abdominal-effusion-4-สาขาสาเหตุ-และ-cut-off-ของ-albumin--v2","statement":"การใช้ hypoalbuminemia เป็นตัวชี้สาเหตุของน้ำในช่องท้องมีความแม่นยำต่ำ ในสุนัข 49 ตัวที่มี transudative abdominal effusion ความแม่นยำโดยรวมของ hypoalbuminemia ในการทำนาย portal hypertension อยู่ที่ 57.1% ซึ่งต่ำกว่า serum albumin-effusion albumin gradient ที่ 69.4%","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11110383","locator":"Abstract, results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The overall diagnostic accuracy of the SA-EA gradient in predicting portal hypertension in dogs with and without hepatobiliary disease (69.4%) exceeded that of hypoalbuminemia (57.1%)."}},{"id":"poa-clinical--poa-edema--abdominal-effusion-4-สาขาสาเหตุ-และ-cut-off-ของ-albumin--v3","statement":"ค่า albumin ต่ำกว่า 1.5 g/dl ถูกใช้จริงในเวชปฏิบัติสัตว์เล็กเป็นเกณฑ์ของ hypoalbuminemia ระดับปานกลางถึงรุนแรง เช่นเกณฑ์คัดเข้าของการศึกษาสุนัข protein-losing enteropathy ที่ใช้ serum albumin ต่ำกว่า 15.0 g/L (ต่ำกว่า 1.5 g/dl) หรือมีของเหลวคั่งนอกหลอดเลือด แต่ไม่พบงานวิจัยที่พิสูจน์ว่าต้องต่ำกว่า 1.5 g/dl เท่านั้น hypoalbuminemia จึงจะทำให้เกิด abdominal effusion ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-27159733","locator":"Abstract, Animals/inclusion criteria","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Dogs were included in the study if they had panhypoproteinemia, serum albumin concentration < 15.0 g/L [< 1.5 g/dL] or extravascular fluid accumulation, idiopathic IBD confirmed on histopathology, and complete medical records."}}]},"poa-clinical--poa-edema--portal-hypertension-จำแนกตามตำแหน่งกายวิภาค":{"claims":[{"id":"poa-clinical--poa-edema--portal-hypertension-จำแนกตามตำแหน่งกายวิภาค--v1","statement":"portal hypertension เกิดจากความต้านทานของหลอดเลือดใน portal circulation ที่เพิ่มขึ้น หรือปริมาณเลือดที่ไหลผ่าน portal vein ที่เพิ่มขึ้น หรือทั้งสองอย่างร่วมกัน","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21382073","locator":"Abstract, opening sentence; J Vet Intern Med 2011;25(2):169-86","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Portal hypertension (PH) is the result of increased vascular resistance in the portal circulation, increased portal venous blood flow, or both."}},{"id":"poa-clinical--poa-edema--portal-hypertension-จำแนกตามตำแหน่งกายวิภาค--v2","statement":"ในทางสัตวแพทย์แทบไม่มีการวัด portal pressure โดยตรง การวินิจฉัย portal hypertension จึงมักอนุมานจากภาวะแทรกซ้อนที่พบร่วม ได้แก่ multiple acquired portosystemic shunts, ascites และ hepatic encephalopathy","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21382073","locator":"Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In veterinary medicine, where portal pressure is seldom measured directly, the diagnosis of PH often is inferred from identification of associated complications including multiple acquired portosystemic shunts, ascites, and hepatic encephal"}},{"id":"poa-clinical--poa-edema--portal-hypertension-จำแนกตามตำแหน่งกายวิภาค--v3","statement":"ความผิดปกติของทางออกของเลือดจากตับ (outflow disturbance) ทำให้ตับคั่งเลือดแบบ passive congestion และในสุนัขและแมวมีสาเหตุหลักจากภาวะหัวใจล้มเหลว ซึ่งตรงกับการจัด right-sided heart failure, hepatic vein และ caudal vena cava ไว้ในกลุ่ม posthepatic","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-7571284","locator":"Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Outflow disturbances result in passive congestion of the liver and in both species are mainly due to cardiac failure."}}]},"poa-clinical--poa-edema--สรุปเคส-heartworm-ร่วมกับ-right-sided-chf":{"claims":[{"id":"poa-clinical--poa-edema--สรุปเคส-heartworm-ร่วมกับ-right-sided-chf--v1","statement":"ในโรคพยาธิหนอนหัวใจของสุนัข การมี Dirofilaria immitis อยู่เรื้อรังทำให้เกิด proliferative endoarteritis, thromboembolism, pulmonary hypertension และ right-sided congestive heart failure","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25224789","locator":"Abstract, discussion of disease mechanism","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"In canine heartworm disease, chronic presence of D. immitis causes a proliferative endoarteritis, thromboembolisms, pulmonary hypertension, and right-sided congestive heart failure."}},{"id":"poa-clinical--poa-edema--สรุปเคส-heartworm-ร่วมกับ-right-sided-chf--v2","statement":"สุนัขที่ติดพยาธิหนอนหัวใจส่วนใหญ่ไม่แสดงอาการหรือมีอาการเล็กน้อย แต่อาการแสดงที่รุนแรงเช่นภาวะหัวใจล้มเหลวและ caval syndrome อาจถึงแก่ชีวิตได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-32521392","locator":"Abstract","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Severe manifestations such as heart failure and caval syndrome may prove fatal."}},{"id":"poa-clinical--poa-edema--สรุปเคส-heartworm-ร่วมกับ-right-sided-chf--v3","statement":"จากการผ่าซากสุนัข 1,617 ตัวในระยะ 13 ปี พบติด Dirofilaria immitis 249 ตัว ในจำนวนนี้ 33 ตัว (13.2%) เป็น caval syndrome และกลุ่มนี้พบรอยโรคมหภาคทั้งที่ระบบหัวใจและปอด และที่ตับ","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-25280391","locator":"Abstract, results","kind":"primary-literature"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-02","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Among the 249 positive cases, 33 (13.2%) of the dogs had caval syndrome. Caval syndrome cases presented with concurrent clinical signs and were associated with cardio-pulmonary and hepatic gross lesions at necropsy."}}]}},"poa-clinical--poa-red-urine":{"poa-clinical--poa-red-urine--เคสสุนัขบางแก้ว-epistaxis-2-ข้างร่วมกับไข้-ตั้ง-problem-list":{"claims":[{"id":"poa-clinical--poa-red-urine--เคสสุนัขบางแก้ว-epistaxis-2-ข้างร่วมกับไข้-ตั้ง-problem-list--v1","statement":"การรวม epistaxis เข้ากับไข้ เบื่ออาหาร และเกล็ดเลือดต่ำไว้ใน problem list เดียวกันตรงกับ clinical case definition ของ canine ehrlichiosis ที่ใช้ fever, thrombocytopenia, anorexia, nasolacrimal discharge และ epistaxis ร่วมกับการตัดโรค autoimmune และ vector-borne อื่นออก","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-11193652","locator":"Abstract; vol 916, pp 396-403","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"A clinical diagnosis of canine ehrlichiosis may be based on the manifestation of fever, thrombocytopenia, anorexia, nasolacrimal discharge, epistaxis, and exclusion of autoimmune and common canine vector borne diseases."}},{"id":"poa-clinical--poa-red-urine--เคสสุนัขบางแก้ว-epistaxis-2-ข้างร่วมกับไข้-ตั้ง-problem-list--v2","statement":"petechial hemorrhage เป็นรอยโรคที่พบจริงในสุนัขที่ติด Ehrlichia canis โดยรายงานพยาธิสภาพระบุ petechial และ ecchymotic hemorrhage บนผิว serosa และ mucosa ของหลายอวัยวะ จึงสมเหตุสมผลที่จะบันทึกจุดเลือดออกที่หน้าท้องเป็น problem ที่จำเพาะควบคู่กับ epistaxis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-16512116","locator":"Abstract; vol 6(4), pp 220-225","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Pathological findings consist of petechial and ecchymotic hemorrhages on serosal and mucosal surfaces of numerous organs."}}]},"poa-clinical--poa-red-urine--assessment-epistaxis-local-กับ-systemic-และ-primary-กับ-secondar":{"claims":[{"id":"poa-clinical--poa-red-urine--assessment-epistaxis-local-กับ-systemic-และ-primary-กับ-secondar--v1","statement":"การแบ่งสาเหตุ epistaxis เป็น local กับ systemic ตรงกับข้อมูลจริงจากสุนัข 176 ตัว โดย local ได้แก่ nasal neoplasia, trauma, idiopathic rhinitis และ periapical abscess ส่วน systemic ได้แก่ thrombocytopenia, thrombocytopathia, coagulopathy, hypertension และ vasculitis","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-18081523","locator":"Abstract, Results; vol 231(12), pp 1843-1850","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Local causes of epistaxis included nasal neoplasia (n = 35), trauma (33), idiopathic rhinitis (20), and periapical abscess (2). Systemic causes included thrombocytopenia (12), thrombocytopathia (7), coagulopathy (3), hypertension (2), and v"}},{"id":"poa-clinical--poa-red-urine--assessment-epistaxis-local-กับ-systemic-และ-primary-กับ-secondar--v2","statement":"การจัดภาวะเกล็ดเลือดต่ำไว้ในกลุ่ม primary hemostasis disorder ถูกต้อง เอกสาร consensus ระบุว่า immune thrombocytopenia เป็น acquired primary hemostatic disorder ที่พบบ่อยที่สุดในสุนัข","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-38752421","locator":"Abstract and Introduction; vol 38(4), pp 1958-1981","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Immune thrombocytopenia (ITP) is the most common acquired primary hemostatic disorder in dogs"}}]},"poa-clinical--poa-red-urine--แผนวินิจฉัย-cbc-และการคัดกรอง-blood-parasites":{"claims":[{"id":"poa-clinical--poa-red-urine--แผนวินิจฉัย-cbc-และการคัดกรอง-blood-parasites--v1","statement":"การเลือกคัดกรองสาเหตุติดเชื้อก่อนมีเหตุผลรองรับด้วยข้อมูลระบาด ในสุนัขที่มีภาวะเกล็ดเลือดต่ำ 871 ตัว กลุ่ม inflammatory หรือ infectious เป็นกลุ่มใหญ่ที่สุด 304 ตัว คิดเป็น 34.9 เปอร์เซ็นต์ มากกว่ากลุ่ม immune-mediated ที่มีเพียง 5.6 เปอร์เซ็นต์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-19465753","locator":"Abstract; vol 164(21), pp 647-651","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"immune-mediated thrombocytopenia (49; 5.6 per cent), thrombocytopenia caused by disseminated intravascular coagulation (DIC) (52; 6.0 per cent), thrombocytopenia caused by miscellaneous disorders (222; 25.5 per cent), neoplasia-associated t"}},{"id":"poa-clinical--poa-red-urine--แผนวินิจฉัย-cbc-และการคัดกรอง-blood-parasites--v2","statement":"ชุดตรวจ SNAP 4Dx Plus มีสมรรถนะรองรับการใช้คัดกรองในเคสแบบนี้ โดยมีความไวมากกว่า 90 เปอร์เซ็นต์ (Ehrlichia spp. 93.4 เปอร์เซ็นต์ Anaplasma spp. 94.1 เปอร์เซ็นต์) และความจำเพาะ 96.8 ถึง 100 เปอร์เซ็นต์ อีกทั้งรุ่นที่สองตรวจพบแอนติบอดีได้เร็วขึ้น 3 ถึง 22 วันในระยะ acute","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-36273749","locator":"Abstract, Results; vol 51, article 100735","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"the second-generation test had sensitivities greater than 90% for Anaplasma spp. (94.1%), B burgdorferi (95.5%), Ehrlichia spp. (93.4%) and D immitis (98.0%). Specificity ranged from 96.8% - 100% across the four assays."}}]}},"poa-clinical--poa-respiratory":{"poa-clinical--poa-respiratory--เคสแมวหายใจลำบากหลังแผลถูกกัด-จับ-pattern-และระบุตำแหน่ง":{"claims":[{"id":"poa-clinical--poa-respiratory--เคสแมวหายใจลำบากหลังแผลถูกกัด-จับ-pattern-และระบุตำแหน่ง--v1","statement":"การใช้เสียงปอดที่ลดลงหรือหายไปเพื่อ localize ไปที่ pleural space มีหลักฐานรองรับ ในสุนัขและแมวที่มี respiratory distress 176 ตัว การพบ asynchronous หรือ inverse breathing ร่วมกับเสียงปอดที่ลดลงสัมพันธ์กับ pleural space disease อย่างมีนัยสำคัญ (P น้อยกว่า 0.001) โดยมีความไว 99 เปอร์เซ็นต์ แต่ความจำเพาะเพียง 45 เปอร์เซ็นต์","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-21288289","locator":"Abstract, Results; vol 21(1), pp 13-23","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"An asynchronous or inverse breathing pattern and decreased lung auscultation results were significantly associated with pleural space disease in both dogs and cats (P<0.001). The combination is highly sensitive (99%) but not very specific ("}}]},"poa-clinical--poa-respiratory--เลือกเครื่องมือตามความ-stable-tfast-ก่อนเมื่อยัง-unstable":{"claims":[{"id":"poa-clinical--poa-respiratory--เลือกเครื่องมือตามความ-stable-tfast-ก่อนเมื่อยัง-unstable--v1","statement":"การใช้ TFAST เพื่อตรวจหาของเหลวใน pleural space อย่างรวดเร็วมีหลักฐานรองรับ เมื่อเทียบกับ computed tomography พบว่า FAST ตรวจพบของเหลวอิสระในช่องอกและช่องท้องได้เชื่อถือได้ แต่เอกสารเดียวกันเตือนว่า TFAST ไม่น่าเชื่อถือสำหรับการวินิจฉัย pneumothorax","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-29901282","locator":"Abstract, Conclusions; vol 28(5), pp 429-435","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"FAST exams reliably identify the presence of free fluid in the peritoneal and pleural cavities; however, TFAST is not a reliable method to diagnose pneumothorax in dogs and cats following trauma."}},{"id":"poa-clinical--poa-respiratory--เลือกเครื่องมือตามความ-stable-tfast-ก่อนเมื่อยัง-unstable--v2","statement":"การเลือก point-of-care ultrasound เป็นเครื่องมือแรกในแมวที่ยังไม่ stable มีหลักฐานรองรับจากแมว 51 ตัวที่มี respiratory distress ซึ่ง lung ultrasound และ focused cardiac ultrasound ให้ข้อมูลที่ใช้วินิจฉัยได้จริงข้างเตียง โดยตรวจพบ pleural effusion และประเมินขนาด left atrium ได้","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30216579","locator":"Abstract, Conclusions; vol 32(5), pp 1530-1540","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Point-of-care diagnostic techniques of LUS, FCU, and NT-proBNP are useful to diagnose CHF in cats with respiratory distress."}}]},"poa-clinical--poa-respiratory--อ่านภาพรังสี-ต่อด้วย-thoracocentesis-และ-fluid-analysis":{"claims":[{"id":"poa-clinical--poa-respiratory--อ่านภาพรังสี-ต่อด้วย-thoracocentesis-และ-fluid-analysis--v1","statement":"การอ่านภาพว่าไม่เห็น cardiac silhouette ในเคสนี้ตรงกับเกณฑ์ที่นักรังสีวิทยาใช้จริง โดยจัด pleural effusion ระดับรุนแรงเมื่อพบการลบเลือนของ cardiac silhouette และกะบังลมอย่างสมบูรณ์ ร่วมกับการเบียดเคลื่อนของหลอดลมใหญ่","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35346189","locator":"Methods, definitions of effusion severity; vol 18(1), article 118","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"complete effacement of the cardiac silhouette, diaphragm, and displacement of the trachea"}}]},"poa-clinical--poa-respiratory--เคสชิวาวา-12-ปี-ไอมีเสมหะและหายใจลำบาก-ไล่เหตุผลสู่-mmvd-chf":{"claims":[{"id":"poa-clinical--poa-respiratory--เคสชิวาวา-12-ปี-ไอมีเสมหะและหายใจลำบาก-ไล่เหตุผลสู่-mmvd-chf--v1","statement":"signalment ของ MMVD ที่ระบุว่าเป็นสุนัขพันธุ์เล็กอายุมากถูกต้อง แนวทาง consensus ระบุว่าความชุกสูงกว่าในสุนัขที่เล็กกว่า 20 กิโลกรัม และเพิ่มขึ้นชัดเจนตามอายุ โดยพบรอยโรคที่ลิ้นหัวใจได้ถึง 85 เปอร์เซ็นต์เมื่ออายุ 13 ปี","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30974015","locator":"Introduction and epidemiology section; vol 33(3), pp 1127-1140","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"The prevalence of MMVD increases markedly with age in small breed dogs, with up to 85% showing evidence of the valve lesion by 13 years of age."}}]},"poa-clinical--poa-respiratory--กลไก-cardiovascular-ที่ถูกถามไล่เรียงในเคส-mmvd":{"claims":[{"id":"poa-clinical--poa-respiratory--กลไก-cardiovascular-ที่ถูกถามไล่เรียงในเคส-mmvd--v1","statement":"การอ่าน systolic murmur ที่ left apex ว่าเป็น mitral valve regurgitation ตรงกับแนวทาง consensus ที่เรียกเสียงฟู่ชนิดนี้ว่า typical left apical regurgitant quality murmur แต่แนวทางเดียวกันเตือนว่าการได้ยินเสียงนี้ในสุนัขที่ไอไม่ได้แปลว่าอาการทางคลินิกเกิดจาก CHF เสมอไป","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30974015","locator":"Diagnosis section; vol 33(3), pp 1127-1140","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"Because of the relatively high prevalence of chronic tracheobronchial disease in the population most at risk for MMVD, the presence of a typical left apical regurgitant quality murmur in a coughing dog does not necessarily mean that clinica"}},{"id":"poa-clinical--poa-respiratory--กลไก-cardiovascular-ที่ถูกถามไล่เรียงในเคส-mmvd--v2","statement":"การมองว่า sinus tachycardia ที่จังหวะสม่ำเสมอเป็นสัญญาณของสุนัขที่มีอาการจาก MMVD จริงมีหลักฐานรองรับ แนวทาง consensus ระบุว่าสุนัขที่มี sinus arrhythmia เด่นชัดและอัตราการเต้นหัวใจค่อนข้างช้ามีโอกาสน้อยกว่าที่อาการจะมาจาก MMVD เมื่อเทียบกับสุนัขที่มี sinus rhythm หรือ sinus tachycardia","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-30974015","locator":"Diagnosis section, physical examination; vol 33(3), pp 1127-1140","kind":"guideline"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"dogs with marked sinus arrhythmia and relatively slow heart rates also are less likely to have clinical signs attributable to MMVD than are those with similar clinical signs (eg, cough, dyspnea) with sinus rhythm or sinus tachycardia."}},{"id":"poa-clinical--poa-respiratory--กลไก-cardiovascular-ที่ถูกถามไล่เรียงในเคส-mmvd--v3","statement":"คำอธิบาย respiratory sinus arrhythmia ว่าหัวใจเต้นเร็วตอนหายใจเข้าและช้าตอนหายใจออกถูกต้อง งานวิจัยที่วัด RSA ใช้ผลต่างของ instantaneous heart rate ระหว่างยอดตอนหายใจเข้ากับท้องตอนหายใจออกเป็นนิยามของ RSA และรายงานว่าขนาดของ RSA ในสุนัขสูงถึงประมาณ 40 เปอร์เซ็นต์ของอัตราการเต้นเฉลี่ย","evidenceStatus":"established","reviewStatus":"verified","sourceRefs":[{"sourceId":"pmid-35366757","locator":"Abstract, Methods and Results; vol 47(1), pp 279-284","kind":"journal"}],"review":{"reviewedBy":"reference-verified","reviewedAt":"2026-08-09","method":"reference-cross-check","approvedScopes":["learning","assessment"],"rationale":"For each breath, RSA was the difference in instantaneous heart rate (HR) between the inspiratory peak and the expiratory trough, in percent of mean HR."}}]}}};
